import type { ChargeResult } from "./charge-result"

export type StripeChargeInput = {
  vendor: "stripe"
  amountMinor: number
  currency: string
  paymentMethod: string
  idempotencyKey: string
}

export type StripeGatewayEvent =
  | { kind: "succeeded"; id: string }
  | { kind: "requires_action"; id: string; clientSecret: string }
  | { kind: "card_declined"; id: string }
  | { kind: "rate_limited"; id: string }

export function chargeStripe(input: StripeChargeInput, event: StripeGatewayEvent): ChargeResult {
  if (!Number.isInteger(input.amountMinor) || input.amountMinor <= 0) {
    return { status: "failed", code: "invalid_amount", retryable: false }
  }
  switch (event.kind) {
    case "succeeded":
      return { status: "succeeded", providerRef: event.id }
    case "requires_action":
      return { status: "requires_action", providerRef: event.id, action: event.clientSecret }
    case "card_declined":
      return { status: "failed", code: "card_declined", retryable: false }
    case "rate_limited":
      return { status: "failed", code: "rate_limited", retryable: true }
  }
}

