import { expect, test } from "bun:test"
import { chargeStripe } from "./stripe-adapter"

const input = {
  vendor: "stripe" as const,
  amountMinor: 1000,
  currency: "usd",
  paymentMethod: "pm_card",
  idempotencyKey: "idemp_1",
}

test("stripe requires_action stays requires_action", () => {
  const result = chargeStripe(input, {
    kind: "requires_action",
    id: "ch_auth",
    clientSecret: "sec_3ds",
  })
  expect(result.status).toBe("requires_action")
  if (result.status === "requires_action") {
    expect(result.action).toBe("sec_3ds")
    expect(result.providerRef).toBe("ch_auth")
  }
})

test("stripe card_declined is a non-retryable failure", () => {
  const result = chargeStripe(input, { kind: "card_declined", id: "ch_declined" })
  expect(result).toEqual({ status: "failed", code: "card_declined", retryable: false })
})

test("stripe rate_limited is retryable", () => {
  const result = chargeStripe(input, { kind: "rate_limited", id: "ch_rl" })
  expect(result).toEqual({ status: "failed", code: "rate_limited", retryable: true })
})

test("stripe succeeded returns providerRef", () => {
  const result = chargeStripe(input, { kind: "succeeded", id: "ch_ok" })
  expect(result).toEqual({ status: "succeeded", providerRef: "ch_ok" })
})

