import { expect, test } from "bun:test"
import { capturePaypal } from "./paypal-adapter"

const input = {
  vendor: "paypal" as const,
  amountMinor: 2500,
  currency: "usd",
  orderId: "ord_1",
}

test("paypal PENDING capture stays pending", () => {
  const result = capturePaypal(input, { kind: "PENDING", id: "cap_pending" })
  expect(result.status).toBe("pending")
  if (result.status === "pending") {
    expect(result.providerRef).toBe("cap_pending")
  }
})

test("paypal PAYEE_NOT_VERIFIED is a non-retryable failure", () => {
  const result = capturePaypal(input, { kind: "PAYEE_NOT_VERIFIED", id: "cap_unverified" })
  expect(result).toEqual({
    status: "failed",
    code: "payee_not_verified",
    retryable: false,
  })
})

test("paypal COMPLETED succeeds", () => {
  const result = capturePaypal(input, { kind: "COMPLETED", id: "cap_ok" })
  expect(result).toEqual({ status: "succeeded", providerRef: "cap_ok" })
})

test("paypal INSTRUMENT_DECLINED is a non-retryable failure", () => {
  const result = capturePaypal(input, { kind: "INSTRUMENT_DECLINED", id: "cap_declined" })
  expect(result).toEqual({
    status: "failed",
    code: "instrument_declined",
    retryable: false,
  })
})

