import { expect, test } from "bun:test"
import { charge } from "./orchestrator"

test("orchestrator dispatches stripe without exposing gateway event kinds as results", () => {
  const result = charge({
    vendor: "stripe",
    input: {
      vendor: "stripe",
      amountMinor: 400,
      currency: "usd",
      paymentMethod: "pm_1",
      idempotencyKey: "k",
    },
    event: { kind: "requires_action", id: "ch_1", clientSecret: "sec" },
  })
  expect(result.status).toBe("requires_action")
})

test("orchestrator dispatches paypal pending", () => {
  const result = charge({
    vendor: "paypal",
    input: { vendor: "paypal", amountMinor: 400, currency: "usd", orderId: "o1" },
    event: { kind: "PENDING", id: "cap_1" },
  })
  expect(result.status).toBe("pending")
})

