import type { ChargeResult } from "./charge-result"
import { UnifiedVendorAdapter } from "./unified-adapter"
import type { StripeChargeInput, StripeGatewayEvent } from "./stripe-types"

export type { StripeChargeInput, StripeGatewayEvent }

export function chargeStripe(input: StripeChargeInput, event: StripeGatewayEvent): ChargeResult {
  if (!Number.isInteger(input.amountMinor) || input.amountMinor <= 0) {
    return { status: "failed", code: "invalid_amount", retryable: false }
  }
  const adapter = new UnifiedVendorAdapter()
  const extra = event.kind === "requires_action" ? event.clientSecret : undefined
  return adapter.normalize(event.kind, event.id, extra)
}

