export function invoiceTotal(lines: { minor: number }[]): number {
  let total = 0
  for (const line of lines) {
    if (!Number.isInteger(line.minor) || line.minor < 0) {
      throw new Error("line_not_nonnegative_integer")
    }
    total += line.minor
  }
  if (!Number.isInteger(total) || total < 0) {
    throw new Error("total_not_nonnegative_integer")
  }
  return total
}

export function refundAmount(originalMinor: number, requestedMinor: number): number {
  if (!Number.isInteger(originalMinor) || originalMinor < 0) {
    throw new Error("original_not_nonnegative_integer")
  }
  if (!Number.isInteger(requestedMinor) || requestedMinor < 0) {
    throw new Error("requested_not_nonnegative_integer")
  }
  if (requestedMinor > originalMinor) {
    throw new Error("refund_exceeds_original")
  }
  return requestedMinor
}

