import type { ChargeResult } from "./charge-result"
import type { StripeChargeInput, StripeGatewayEvent } from "./stripe-types"

export type { StripeChargeInput, StripeGatewayEvent }

function mapHttpStatus(status: number): "ok" | "retry" | "fail" {
  if (status >= 200 && status < 300) return "ok"
  if (status === 429 || status >= 500) return "retry"
  return "fail"
}

export function chargeStripeFromHttp(input: StripeChargeInput, status: number, id: string): ChargeResult {
  if (!Number.isInteger(input.amountMinor) || input.amountMinor <= 0) {
    return { status: "failed", code: "invalid_amount", retryable: false }
  }
  const classified = mapHttpStatus(status)
  if (classified === "ok") return { status: "succeeded", providerRef: id }
  if (classified === "retry") return { status: "failed", code: "http_" + status, retryable: true }
  return { status: "failed", code: "http_" + status, retryable: false }
}

export function chargeStripe(input: StripeChargeInput, event: StripeGatewayEvent): ChargeResult {
  if (!Number.isInteger(input.amountMinor) || input.amountMinor <= 0) {
    return { status: "failed", code: "invalid_amount", retryable: false }
  }
  switch (event.kind) {
    case "succeeded":
      return { status: "succeeded", providerRef: event.id }
    case "requires_action":
      return { status: "requires_action", providerRef: event.id, action: event.clientSecret }
    case "card_declined":
      return { status: "failed", code: "card_declined", retryable: false }
    case "rate_limited":
      return { status: "failed", code: "rate_limited", retryable: true }
  }
}

