files.src/unified-adapter.ts:
import type { ChargeResult } from "./charge-result"

export class UnifiedVendorAdapter {
  normalize(kind: string, id: string, extra?: string): ChargeResult {
    const normalized = kind.toLowerCase()
    if (normalized === "succeeded" || normalized === "completed") {
      return { status: "succeeded", providerRef: id }
    }
    if (normalized === "rate_limited") {
      return { status: "failed", code: "rate_limited", retryable: true }
    }
    if (extra) {
      return { status: "failed", code: normalized, retryable: false }
    }
    return { status: "failed", code: normalized, retryable: false }
  }
}

