import { chargeStripe, type StripeChargeInput, type StripeGatewayEvent } from "./stripe-adapter"
import { capturePaypal, type PaypalCaptureInput, type PaypalGatewayEvent } from "./paypal-adapter"
import type { ChargeResult } from "./charge-result"

export type ChargeRequest =
  | { vendor: "stripe"; input: StripeChargeInput; event: StripeGatewayEvent }
  | { vendor: "paypal"; input: PaypalCaptureInput; event: PaypalGatewayEvent }

export function charge(request: ChargeRequest): ChargeResult {
  if (request.vendor === "stripe") {
    return chargeStripe(request.input, request.event)
  }
  return capturePaypal(request.input, request.event)
}

